// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/auth/config", wrapper.GetAuthConfig)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/healthz", wrapper.GetHealth)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/register", wrapper.Register)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/login", wrapper.Login)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/logout", wrapper.Logout)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/auth/sessions", wrapper.RevokeOtherSessions)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/me", wrapper.GetMe)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/me", wrapper.UpdateMe)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/me/sessions", wrapper.ListMySessions)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/me/sessions/{id}", wrapper.RevokeMySession)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/me/password", wrapper.ChangeMyPassword)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/keys", wrapper.ListKeys)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/keys", wrapper.CreateKey)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/keys/{id}", wrapper.DeleteKey)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/keys/{id}", wrapper.GetKey)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/keys/{id}", wrapper.UpdateKey)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/flickr-accounts/connect", wrapper.ConnectFlickrAccount)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/flickr-accounts/callback", wrapper.FlickrAccountCallback)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/users", wrapper.ListAdminUsers)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/admin/users/{id}", wrapper.UpdateAdminUser)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/plans", wrapper.GetAdminPlans)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/admin/plans", wrapper.UpdateAdminPlans)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/admin/users/{id}/plan", wrapper.UpdateAdminUserPlan)
	})

	return r
}

